import numpy as np


class KappaCalculator:

    @staticmethod
    def kappa(test_data, k):
        return KappaCalculator._calculate_cohens_kappa(test_data, k)

    @staticmethod
    def _calculate_cohens_kappa(test_data, k):
        data_mat = np.mat(test_data)
        observed_agreement = KappaCalculator._calculate_observed_agreement(data_mat, k)
        expected_agreement = KappaCalculator._calculate_expected_agreement(data_mat)
        return KappaCalculator._compute_kappa(observed_agreement, expected_agreement)

    @staticmethod
    def _calculate_observed_agreement(data_mat, k):
        total = np.sum(data_mat)
        diagonal_sum = np.sum(np.diag(data_mat, 0))
        return float(diagonal_sum) / total

    @staticmethod
    def _calculate_expected_agreement(data_mat):
        total = np.sum(data_mat)
        row_sums = np.sum(data_mat, axis=1)
        col_sums = np.sum(data_mat, axis=0)
        expected = np.sum(row_sums * col_sums) / (total * total)
        return float(expected)

    @staticmethod
    def _compute_kappa(observed_agreement, expected_agreement):
        return float((observed_agreement - expected_agreement) / (1 - expected_agreement))

    @staticmethod
    def fleiss_kappa(test_data, n_items, k_categories, n_reviews):
        return KappaCalculator._calculate_fleiss_kappa(test_data, n_items, k_categories, n_reviews)

    @staticmethod
    def _calculate_fleiss_kappa(test_data, n_items, k_categories, n_reviews):
        data_mat = np.mat(test_data, dtype=float)
        observed_agreement = KappaCalculator._calculate_fleiss_observed_agreement(
            data_mat, n_items, k_categories, n_reviews
        )
        expected_agreement = KappaCalculator._calculate_fleiss_expected_agreement(
            data_mat, k_categories, n_items, n_reviews
        )
        return float(KappaCalculator._compute_kappa(observed_agreement, expected_agreement))

    @staticmethod
    def _calculate_fleiss_observed_agreement(data_mat, n_items, k_categories, n_reviews):
        total = 0.0
        p0_sum = 0.0
        for i in range(n_items):
            row_sum = np.sum(data_mat[i, :])
            total += row_sum
            squared_sum = np.sum(data_mat[i, :] ** 2)
            p0_sum += (squared_sum - n_reviews) / ((n_reviews - 1) * n_reviews)
        return p0_sum / n_items

    @staticmethod
    def _calculate_fleiss_expected_agreement(data_mat, k_categories, n_items, n_reviews):
        total = np.sum(data_mat)
        col_sums = np.sum(data_mat, axis=0)
        proportions = (col_sums / total) ** 2
        return float(np.sum(proportions))
